<?php
require 'page-guard.php';require '../config/db_conn.php';require '../includes/xlsx-export.php';$section=$_SESSION['teacher-section'];$date=$_GET['date']??date('Y-m-d');$student=trim($_GET['student']??'');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){http_response_code(400);exit('Invalid date.');}$stmt=$conn->prepare("SELECT a.STUDENT_ID,COALESCE(s.STUDENT_NAME,a.STUDENT_NAME) STUDENT_NAME,s.SECTION,a.TIME_IN FROM attendance a INNER JOIN students s ON TRIM(a.STUDENT_ID)=TRIM(s.STUDENT_ID) WHERE s.SECTION=? AND DATE(a.TIME_IN)=? AND (?='' OR a.STUDENT_ID=?) ORDER BY STUDENT_NAME");$stmt->bind_param('ssss',$section,$date,$student,$student);$stmt->execute();$result=$stmt->get_result();$rows=[];while($row=$result->fetch_assoc())$rows[]=[ $row['STUDENT_ID'],$row['STUDENT_NAME'],$row['SECTION'],$date,$row['TIME_IN'],'Present'];downloadAttendanceXlsx('attendance-'.preg_replace('/[^A-Za-z0-9_-]/','_',$section).'-'.$date.'.xlsx',['Student ID','Student Name','Section','Date','Time In','Status'],$rows);